good_bad = input().strip()
k = int(input())

# Create a mapping from character to whether it's good or bad
is_good = {}
for i in range(26):
    char = chr(ord('a') + i)
    is_good[char] = (good_bad[i] == '1')

# Count bad characters for each substring
bad_count = {}
result = 0

for start in range(len(s)):
    bad_chars = 0
    for end in range(start, len(s)):
        char = s[end]
        if not is_good[char]:
            bad_chars += 1

        # If we've seen this substring before, skip
        if s[start:end+1] in bad_count:
            continue

        bad_count[s[start:end+1]] = bad_chars

        # If the number of bad characters is within limit, count it
        if bad_chars <= k:
            result += 1

print(result)
"}

