import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    moves = 0

    for i in range(1, n):
        # a[i-1] is the previous element, a[i] is the current element
        if a[i-1] < a[i]:
            continue

        diff = a[i-1] - a[i]
        moves += diff

    print(moves)

if __name__ == "__main__":
    solve()
"}

