MOD = 10**9 + 7

def char_to_value(c):
    if '0' <= c <= '9':
        return ord(c) - ord('0')
    elif 'A' <= c <= 'Z':
        return ord(c) - ord('A') + 10
    elif 'a' <= c <= 'z':
        return ord(c) - ord('a') + 36
    elif c == '-':
        return 62
    elif c == '_':
        return 63

def solve():
    s = input().strip()
    result = 1
    for c in s:
        val = char_to_value(c)
        for i in range(6):
            bit = (val >> (5 - i)) & 1
            if bit == 0:
                result = (result * 3) % MOD
            else:
                result = (result * 1) % MOD
    print(result)

solve()
