import sys

def is_great(length, lengths):
    """Check if a choice with given length is great"""
    # Check if at least twice shorter than all others
    if all(length * 2 <= l for l in lengths):
        return True

    # Check if at least twice longer than all others
    if all(l * 2 <= length for l in lengths):
        return True

    return False

def solve():
    lines = sys.stdin.read().strip().split('\n')

    # Extract lengths
    lengths = []
    for i, line in enumerate(lines):
        # Skip the prefix "X." and get the description
        desc = line[len(f"{"ABCD"[i]}") + 1:]
        lengths.append(len(desc))

    # Find great choices
    great_choices = []
    for i, length in enumerate(lengths):
        if is_great(length, lengths):
            great_choices.append(i)

    # Determine the answer
    if len(great_choices) == 1:
        return chr(ord('A') + great_choices[0])
    else:
        return 'C'

if __name__ == "__main__":
    print(solve())
"}

