n, k, x = map(int, input().split())
a = list(map(int, input().split()))

# DP[i][j][c]: maximum sum when considering first i pictures,
# with j consecutive unselected pictures at position i,
# and having selected c pictures
INF = -1

# Initialize DP table
# dp[i][j][c] where 0 <= j <= k-1, 0 <= c <= x
# We'll use a 2D array for each position

dp = [[[-1 for _ in range(x + 1)] for _ in range(k)] for _ in range(n + 1)]

dp[0][0][0] = 0

for i in range(1, n + 1):
    for j in range(k):
        for c in range(x + 1):
            if dp[i-1][j][c] == -1:
                continue

            # Option 1: Select picture i
            if c + 1 <= x:
                dp[i][0][c + 1] = max(dp[i][0][c + 1], dp[i-1][j][c] + a[i-1])

            # Option 2: Don't select picture i
            if j + 1 < k:
                dp[i][j + 1][c] = max(dp[i][j + 1][c], dp[i-1][j][c])

# Check all valid states at position n
result = -1
for j in range(k):
    for c in range(x + 1):
        if dp[n][j][c] != -1 and c == x:
            result = max(result, dp[n][j][c])

print(result if result != -1 else -1
"}

