            # Option 1: Select picture i
            if c + 1 <= x:
                dp[i][0][c + 1] = max(dp[i][0][c + 1], dp[i-1][j][c] + a[i-1])

            # Option 2: Don't select picture i
            if j + 1 < k:
                dp[i][j + 1][c] = max(dp[i][j + 1][c], dp[i-1][j][c])

