import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Track how many pizzas we need to satisfy on each day
    need = a.copy()

    # Process each day
    for i in range(n):
        # Use discount 1 for as many as possible
        discount1 = min(2, need[i])
        need[i] -= discount1

        # Use discount 2 for the remaining
        if need[i] > 0:
