def cross(p1, p2, p3):
    """Check if point p3 is on the line segment p1-p2"""
    def on_segment(p, q, r):
        # Check if point q lies on line segment pr
        if min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1]):
            return True
        return False

    # Check if vectors p1p2 and p1p3 are collinear
    def collinear(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) == (p3[0] - p1[0]) * (p2[1] - p1[1])

    # Check if segment p1-p2 intersects with segment p3-p4
    def segment_intersect(p1, p2, p3, p4):
        # Check if line segments p1-p2 and p3-p4 intersect
        if collinear(p1, p2, p3) or collinear(p1, p2, p4):
            return on_segment(p1, p2, p3) or on_segment(p1, p2, p4)

        # Check if segments cross each other
        def orientation(p, q, r):
            val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
            if val == 0:
                return 0  # collinear
            return 1 if val > 0 else 2  # clockwise or counterclockwise

        o1 = orientation(p1, p2, p3)
        o2 = orientation(p1, p2, p4)
        o3 = orientation(p3, p4, p1)
        o4 = orientation(p3, p4, p2)

        # General case
        if o1 != o2 and o3 != o4:
            return True

        # Special Cases
        if o1 == 0 and on_segment(p1, p2, p3):
            return True
        if o2 == 0 and on_segment(p1, p2, p4):
            return True
        if o3 == 0 and on_segment(p3, p4, p1):
            return True
        if o4 == 0 and on_segment(p3, p4, p2):
            return True

        return False

    # Check if point p is inside polygon poly
    def point_in_polygon(p, poly):
        n = len(poly)
        inside = False
        for i in range(n):
            p1 = poly[i]
            p2 = poly[(i + 1) % n]
            if p1[2] == p2[2]:
                # Edge is on the same plane as p
                continue

            # Check if point is on the line segment
            if on_segment(p1, p2, p):
                return True

            # Determine which side of the line the point is on
            def cross_product(p3, p4, p):
                return (p4[0] - p3[0]) * (p[1] - p3[1]) - (p4[1] - p3[1]) * (p[0] - p3[0])

            val = cross_product(p1, p2, p)
            if val < 0:
                inside = not inside

        return inside

    # Check if edge e1-e2 crosses the polygon poly
    def edge_crosses_polygon(e1, e2, poly):
        n = len(poly)
        for i in range(n):
            p1 = poly[i]
            p2 = poly[(i + 1) % n]
            if segment_intersect(e1, e2, p1, p2):
                return True

        # Check if either endpoint is inside the polygon
        if point_in_polygon(e1, poly) or point_in_polygon(e2, poly):
            return True

        return False

    return edge_crosses_polygon(e1, e2, poly)

