import sys

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    for _ in range(t):
        n = int(next(it))
        x = [int(next(it)) for _ in range(n)]

        # Count how many numbers have each bit set
        count = [0] * 60
        for num in x:
            for b in range(60):
                if num & (1 << b):
                    count[b] += 1

        # Compute A * B for each x_j
        total = 0
        for num in x:
            # A = sum over all i of (x_i & num)
            # A = sum over bits b set in num of 2^b * count[b]
            A = 0
            for b in range(60):
                if num & (1 << b):
                    A += (1 << b) * count[b]

            # B = sum over all k of (num | x_k)
            # B = n * num + sum over bits b not set in num of 2^b * count[b]
            B = n * num + (sum(count) * 2**1 - num)

            total += A * B
            total %= MOD

        print(total % MOD)

if __name__ == "__main__":
    solve()
