def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    t = int(data[0])
    results = []

    idx = 1
    for _ in range(t):
        s = int(data[idx])
        e = int(data[idx + 1])
        idx += 2

        # Let's use BFS to determine if Lee can always win or always lose
        # State: (value, player_turn) where player_turn = 0 (Lee) or 1 (Ice Bear)

        # Winning states: (value, player_turn) where the current player can force a win
        # Losing states: (value, player_turn) where the current player cannot avoid losing

        from collections import deque

        # Initialize queue with (s, 0) if Lee starts first
        queue = deque([(s, 0)])

        visited = set()
        winning_states = {}  # True means current player can force a win

        while queue:
            value, player_turn = queue.popleft()

            if (value, player_turn) in visited:
                continue

            visited.add((value, player_turn))

            if value > e:
                winning_states[(value, player_turn)] = False  # Current player loses
            elif value == e:
                winning_states[(value, player_turn)] = True   # Game over, current player wins
            else:
                # Determine if current player can force a win
                if player_turn == 0:
                    # Lee's turn
                    move_double = 2 * value
                    move_add_one = value + 1

                    can_win = False

