import sys

def can_win(v, e):
    """Determine if the starting player can force a win"""
    if v > e:
        return False  # already lost

    if v == e:
        return False  # any move loses

    # Check if both moves lose
    if 2 * v > e and v + 1 > e:
        return False

    # At least one move is valid
    # If there's a move that leads to opponent losing, we win
    if 2 * v > e:
        return True
    if v + 1 > e:
        return True

    # Both moves are valid, need to check if opponent can win from both
    return not (can_win(2 * v, e) and can_win(v + 1, e))


