def solve_round(s, e):
    """Determine if Lee can win and lose for a single round"""
    # Can Lee win (starting player can win)
    # Can Lee lose (starting player can lose)

    # If s > e: Lee already lost, so he can't win and must lose
    if s > e:
        return (0, 1)

    # If s == e: Lee loses immediately
    if s == e:
        return (0, 1)

    # If s < e:
    # Check if both moves lead to > e
    if 2 * s > e and s + 1 > e:
        # Both moves lose, so Lee loses
        return (0, 1)

