        # Lee can make v+1 and avoid loss
        # Ice Bear then starts from s+1
        # Ice Bear can win if s+1 >= e or if both moves from s+1 lead to > e
        # Let's compute if Ice Bear can win from s+1
        ice_bear_can_win = False
        if s + 1 > e:
            ice_bear_can_win = True
        elif 2 * (s + 1) > e and (s + 1) + 1 > e:
            ice_bear_can_win = True
        else:
            # Ice Bear starts from s+1, Lee starts from s
            # We need to check if Lee can win from s
            # Lee can make 2*s or s+1
            # If 2*s > e, Lee loses
            if 2 * s > e:
                ice_bear_can_win = True
            else:
                # Lee makes 2*s, Ice Bear starts from 2*s
                # Ice Bear can win if 2*s >= e or both moves from 2*s lead to > e
                if 2 * s >= e:
