        # If Lee makes 2*s, Ice Bear starts from 2*s
        # If Lee makes s+1, Ice Bear starts from s+1
        # Ice Bear can win if either starting point leads to win for Ice Bear

        # Check if Lee can force a loss (Ice Bear wins)
        ice_bear_can_win_from_2s = False
        if 2 * s >= e:
            ice_bear_can_win_from_2s = True
        elif 2 * (2 * s) > e and (2 * s) + 1 > e:
            ice_bear_can_win_from_2s = True

