import sys

def can_win(v, e):
    """Determine if the starting player can force a win"""
    if v > e:
        return False  # already lost

    if v == e:
        return False  # any move loses

    # Check if both moves lose
    if 2 * v > e and v + 1 > e:
        return False

    # At least one move is valid
    # If there's a move that leads to opponent losing, we win
    if 2 * v > e:
        return True
    if v + 1 > e:
        return True

    # Both moves are valid, need to check if opponent can win from both
    return not (can_win(2 * v, e) and can_win(v + 1, e))


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])

    can_win_all = True
    can_lose_all = True

    for i in range(t):
        s = int(data[1 + 2 * i])
        e = int(data[2 + 2 * i])

        # Check if Lee can force a win
        lee_can_win = can_win(s, e)

        # Check if Lee can force a loss (Ice Bear can win no matter Lee's move)
        ice_bear_can_win_from_2s = False
        if 2 * s > e:
            ice_bear_can_win_from_2s = True
        elif can_win(2 * s, e):
            ice_bear_can_win_from_2s = True

        ice_bear_can_win_from_s_plus_1 = False
        if s + 1 > e:
            ice_bear_can_win_from_s_plus_1 = True
        elif can_win(s + 1, e):
            ice_bear_can_win_from_s_plus_1 = True

        lee_can_lose = ice_bear_can_win_from_2s and ice_bear_can_win_from_s_plus_1

        # Update totals
        can_win_all &= lee_can_win
        can_lose_all &= lee_can_lose

