result = ['.'] * n

if k == 0:
    # No bullets, all empty
    pass
elif k == n:
    # All bullets
    result = ['X'] * n
else:
    # Calculate starting position
    if n % k == 0:
        start = n  # Even division, start from the end
    else:
        start = n - (n % k)  # Uneven division, start earlier

    # Place bullets stepping back by (n // k)
    for i in range(k):
        pos = start - i * (n // k)

        # If we went below 1, wrap around to the end
        if pos <= 0:
            pos += n

        result[pos - 1] = 'X'

