def solve():
    n, k, x = map(int, input().split())
    a = list(map(int, input().split()))

    # If k = 1, we must repost all pictures
    if k == 1:
        if x == n:
            print(sum(a))
        else:
            print(-1)
        return

    # DP table: dp[i][j] = maximum sum when considering first i pictures, with j reposts used
    # And the last repost is at position i (1-indexed)
    # We need to track the last position of a repost

    # Initialize DP table with -infinity
    INF = -10**18
    dp = [[INF] * (x + 1) for _ in range(n + 1)]

    # Base case: No pictures considered, 0 reposts used
    dp[0][0] = 0

    for i in range(1, n + 1):
        # Try not placing a repost at position i
        # We need to ensure that the last k-1 pictures (including i) don't all have no repost
        # This means the last repost must be within the last k-1 pictures
        for j in range(x + 1):
            # Check if we can transition from dp[i-1][j] to dp[i][j]
            # This is always valid because dp[i-1][j] has a valid configuration
            if dp[i-1][j] > INF:
                dp[i][j] = max(dp[i][j], dp[i-1][j])

    # Try placing a repost at position i
    for i in range(1, n + 1):
        for j in range(1, x + 1):
            # We can place a repost at i if the last k-1 pictures (from i-k+1 to i) have at least one
            # Actually, we can always place a repost at i, but we need to check the spacing
            # The last repost before i must be at position >= i - k + 1
            for prev in range(max(1, i - k + 1), i):
                if dp[prev][j-1] > INF:
                    dp[i][j] = max(dp[i][j], dp[prev][j-1] + a[i-1])

    # Check if we can satisfy the conditions with x reposts
    # We need the last k pictures to have at least one repost
    result = -1
    for j in range(x + 1):
        if dp[n][j] > INF:
            # Check if the first k pictures have at least one repost
            if dp[k][j] > INF:
                result = dp[n][j]

    print(result if result != -1 else -1)

solve()
