    s = input().strip()

    # For each character, count the number of valid pairs (a, b)
    result = 1

    for c in s:
        val = char_to_value(c)
        # Convert to 6-bit binary string
        bits = bin(val)[2:].zfill(6)

        # Count possibilities for this character
        count = 1
        for bit in bits:
            if bit == '0':
                count = (count * 2) % MOD
            else:
                pass  # bit is 1, no change

        result = (result * count) % MOD

    print(result)

