def non_trivial_divisors(n):
    """Return a set of non-trivial divisors of n"""
    if n < 2:
        return set()
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            if i != n:
                divisors.add(i)
            if n // i != n and n // i != i:
                divisors.add(n // i)
    return divisors

def is_winning_position(n):
    """Check if n is a winning position"""
    divisors = non_trivial_divisors(n)
    if not divisors:
        return True  # No moves, current player wins
    for d in divisors:
        if not is_winning_position(d):
            return False  # Found a move to a losing position
    return True  # All moves lead to winning positions

