import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        x = int(data[idx + 1])
        idx += 2

        # Build adjacency list
        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(data[idx])
            v = int(data[idx + 1])
            adj[u].append(v)
            adj[v].append(u)
            idx += 2

        # Count number of nodes in the subtree rooted at x (including x)
        def count_subtree(u, parent):
            count = 1
            for v in adj[u]:
                if v != parent:
                    count += count_subtree(v, u)
            return count

        subtree_count = count_subtree(x, -1)

        # If x is a leaf, Ayush wins
        if len(adj[x]) == 0:
            print("Ayush")
        # If x has degree 1, Ayush wins
        elif len(adj[x]) == 1:
            print("Ayush")
        # Otherwise, use parity of subtree count
        else:
            if subtree_count % 2 == 1:
                print("Ayush")
            else:
                print("Ashish")

solve()
