import sys

def solve():
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()

    if k == 0:
        print(s)
        return

    if n == 1:
        # can change to 0 if k >= 1
        if k >= 1:
            print('0')
        else:
            print(s)
        return

    # n >= 2
    s = list(s)

    # change first digit to 1 if possible
    if s[0] > '1' and k >= 1:
        s[0] = '1'
        k -= 1

    # change subsequent digits to 0 if possible
    for i in range(1, n):
        if k > 0 and s[i] != '0':
            s[i] = '0'
            k -= 1

    print(''.join(s))

if __name__ == '__main__':
    solve()
"}

