def char_to_value(c):
    if '0' <= c <= '9':
        return ord(c) - ord('0')
    elif 'A' <= c <= 'Z':
        return ord(c) - ord('A') + 10
    elif 'a' <= c <= 'z':
        return ord(c) - ord('a') + 36
    elif c == '-':
        return 62
    elif c == '_':
        return 63

MOD = 10**9 + 7

s = input().strip()
result = 1

for c in s:
    val = char_to_value(c)
    # Count number of 0 bits in val
    zero_bits = bin(val).count('0')
    # Compute 3^zero_bits mod MOD
    result = (result * pow(3, zero_bits, MOD)) % MOD

print(result)
"}

