low = -2 * 10**9
high = 2 * 10**9

for _ in range(n):
    parts = input().split()
    sign, x, answer = parts[0], int(parts[1]), parts[2]

    if answer == 'Y':
        if sign == '>':
            low = x + 1
        elif sign == '<':
            high = x - 1
        elif sign == '>=':
            low = x
        elif sign == '<=':
            high = x
    else:  # answer == 'N'
        if sign == '>':
            high = x
        elif sign == '<':
            low = x
        elif sign == '>=':
            high = x - 1
        elif sign == '<=':
