import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    q = int(sys.stdin.readline())
    queries = [int(sys.stdin.readline()) for _ in range(q)]

    # For each position, keep track of (gcd_value, count)
    # where count is the number of subarrays ending at this position with that gcd
    pos_gcd_counts = []

    for i in range(n):
        current = {}
        val = a[i]

        # Add the subarray consisting of just this element
        current[val] = current.get(val, 0) + 1

        # Merge with previous position's counts
        if i > 0:
            prev = pos_gcd_counts[i-1]
            for g, cnt in prev.items():
                new_gcd = math.gcd(g, val)
                current[new_gcd] = current.get(new_gcd, 0) + cnt

        pos_gcd_counts.append(current)

    # Count total occurrences of each gcd
    total_gcd_counts = {}
    for counts in pos_gcd_counts:
        for g, cnt in counts.items():
            total_gcd_counts[g] = total_gcd_counts.get(g, 0) + cnt

    # Process queries
    for x in queries:
        print(total_gcd_counts.get(x, 0))

if __name__ == "__main__":
    import math
    solve()
