    # If k is small, just find the k-th small divisor
    if k <= num_small:
        print(small_divisors[k-1])
    else:
        # We need the (k - num_small)-th large divisor
        # Large divisors are n // small_divisors[i] for i from num_small-1 down to 0

        # Find the index in small_divisors
        index_in_small = num_small - (k - num_small)

        # If n is a perfect square, the sqrt divisor is counted once, so we need to be careful
        if index_in_small >= 0:
            print(n // small_divisors[index_in_small])
        else:
            print(-1)
