    a = list(map(int, input().split()))

    max_len = 1
    left = 0

    for right in range(n):
        # Check if subsegment [left, right] is valid
        # We need to check if it can be made strictly increasing with <= 1 change

        # For this, we need to count bad positions
        bad = 0
        for i in range(left, right):
            if a[i] >= a[i + 1]:
                bad += 1
                if bad > 1:
