def gcd(x, y):
    """Compute greatest common divisor"""
    while y:
        x, y = y, x % y
    return x

count = {}

for i in range(n):
    # Dictionary to store GCD values of subarrays ending at position i
    curr = {}

    # For each subarray ending at position i-1, we extend it to include a[i]
    for g, cnt in count.items():
        new_gcd = gcd(g, a[i])
        if new_gcd in curr:
            curr[new_gcd] += cnt
        else:
            curr[new_gcd] = cnt

    # Add the subarray consisting of just a[i]
    if a[i] in curr:
        curr[a[i]] += 1
    else:
        curr[a[i]] = 1

    # Merge curr into the global count
    for g, cnt in curr.items():
        if g in count:
            count[g] += cnt
        else:
            count[g] = cnt

# Process queries
for x in queries:
    print(count.get(x, 0))
