a = list(map(int, input().split()))
q = int(input())
queries = [int(input()) for _ in range(q)]

def gcd(x, y):
    """Compute greatest common divisor"""
    while y:
        x, y = y, x % y
    return x

count = {}
curr = {}

for i in range(n):
    new_curr = {}

    # Extend subarrays from previous position
    for g, cnt in curr.items():
        new_gcd = gcd(g, a[i])
        if new_gcd in new_curr:
            new_curr[new_gcd] += cnt
        else:
            new_curr[new_gcd] = cnt

    # Add subarray consisting of just a[i]
    if a[i] in new_curr:
        new_curr[a[i]] += 1
    else:
        new_curr[a[i]] = 1

    # Merge new_curr into global count
    for g, cnt in new_curr.items():
        if g in count:
            count[g] += cnt
        else:
            count[g] = cnt

    # Prepare for next iteration
    curr = new_curr.copy()

# Process queries
for x in queries:
    print(count.get(x, 0))
