def count_valid(n):
    """Count all numbers with exactly n digits where first digit = last digit."""
    if n == 1:
        return 9
    return 9 * (10 ** (n - 2))

def count_in_range(n, r):
    """Count numbers with exactly n digits where first digit = last digit and number <= r."""
    if n == 1:
        return min(r, 9)

    # Minimum and maximum values with exactly n digits
    min_val = 10 ** (n - 1)
    max_val = (10 ** n) - 1

    if r < min_val:
        return 0
    if r >= max_val:
        return count_valid(n)

    # First digit of r
    first_digit = r // (10 ** (n - 1))

    # Numbers with first digit less than the first digit of r
    count = first_digit - 1

    # Numbers with first digit equal to the first digit of r
    # Middle digits: 10^(n-2) combinations
    count += 10 ** (n - 2)

    # Check if the number itself is <= r
    # The maximum number with first digit = first_digit and last digit = first_digit
    max_with_same_first_last = first_digit * (10 ** (n - 1)) + (first_digit - 1) * (10 ** (n - 2)) + first_digit

    if r >= max_with_same_first_last:
        count += 1

    return count

def count_in_range(l, r):
    """Count numbers in [l, r] where first digit = last digit."""
    count = 0

    # Count numbers with first digit = last digit and <= r
    for n in range(1, 19):  # Numbers can have up to 18 digits
        if r < 10 ** (n - 1):
            break
        count += count_in_range(n, r)

    # Count numbers with first digit = last digit and < l
    for n in range(1, 19):
        if l < 10 ** (n - 1):
            break
        count -= count_in_range(n, l - 1)

    return count

# Read input
l, r = map(int, input().split())

# Calculate and print result
print(count_in_range(l, r))
