def count_equal_ends_in_range(l, r):
    count = 0

    # For each possible number of digits
    for length in range(1, len(str(r)) + 1):
        if length == 1:
            # Single-digit numbers: 1-9
            if l <= 9 <= r:
                count += 9 - l + 1
        else:
            # Multi-digit numbers: first digit = last digit
            for first_digit in range(1, 10):
                # Numbers of the form first_digit...first_digit
                start = int(str(first_digit) + '0' * (length - 2) + str(first_digit))
                end = int(str(first_digit) + '9' * (length - 2) + str(first_digit))

                # Count numbers in [l, r]
                lower = max(l, start)
                upper = min(r, end)
                if lower <= upper:
