# freq will store frequency of each gcd value (using a dictionary)
freq = {}  # freq[gcd_value] = count

stack = []  # stack stores tuples (gcd_value, count)

for i in range(n):
    # Process current element
    new_gcd = a[i]

    # Merge intervals with the same gcd value
    temp = []
    while stack and stack[-1][0] == new_gcd:
        top_gcd, top_count = stack.pop()
        temp.append((top_gcd, top_count))

    if temp:
        # If there are elements with the same gcd, merge them
        merged_gcd, merged_count = temp[0]
        for top_gcd, top_count in temp[1:]:
            merged_count += top_count

        # Update frequencies
        for _ in range(merged_count):
            if merged_gcd in freq:
                freq[merged_gcd] += 1
            else:
                freq[merged_gcd] = 1
    else:
        # If no elements with the same gcd, just push the new one
        if new_gcd in freq:
            freq[new_gcd] += 1
        else:
            freq[new_gcd] = 1

    # Push the new gcd value to the stack
    stack.append((new_gcd, 1))

# Print results
for x in queries:
    print(freq.get(x, 0))
