    for _ in range(t):
        n, x = map(int, input().split())
        # Build adjacency list
        from collections import defaultdict
        adj = defaultdict(list)
        for _ in range(n-1):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        # Find branch lengths from x
        branch_lengths = []
        visited = set()
        stack = [(x, 0)]  # (node, depth)
        visited.add(x)

        while stack:
            node, depth = stack.pop()
            if len(adj[node]) == 1 and node != x:  # it's a leaf and not x
                branch_lengths.append(depth)
            else:
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append((neighbor, depth + 1))

        xor_sum = 0
        for length in branch_lengths:
            xor_sum ^= length

        if xor_sum == 0:
            print("Ashish")
        else:
            print("Ayush")

