def count_prime_factors(n):
    """Count the number of prime factors (with multiplicity) of n"""
    if n == 1:
        return 0
    count = 0
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            count += 1
            n //= divisor
        divisor += 1
    if n > 1:
        count += 1
    return count

q = int(input())
