def solve():
    n = int(input())
    s = input().strip()

    # dp[i][c] = minimum recolors for first i lamps, ending with color c
    # c can be 'R', 'G', 'B'
    INF = float('inf')

    # Initialize for first lamp
    dp = {c: INF for c in ['R', 'G', 'B']}
