            if a[i-1] == b[i-1]:
                continue

            # If not matching, perform operation on prefix of length i
            operations.append(i)

            # Perform the operation: invert and reverse
            # Invert all bits in a[0..i-1]
            a = a[:i] + ''.join(['1' if c == '0' else '0' for c in a[:i]]) + a[i:] 

