def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))
    idx = 0

    t = data[idx]
    idx += 1

    for _ in range(t):
        n, m = data[idx], data[idx+1]
        idx += 2

        c = data[idx:idx+n]
        idx += n

        left_right = [[] for _ in range(n)]  # left to right connections

        for __ in range(m):
            u, v = data[idx]-1, data[idx+1]-1

            left_right[u].append(v)
            idx += 2

        # Find which right vertices are connected to all left vertices
        always_included = []
        for v in range(n):
            connected = set()
            for u in range(n):
                if v in left_right[u]:
                    connected.add(u)
            if len(connected) == n:
                always_included.append(c[v])

        # Find which right vertices are connected to at least one but not all left vertices
        variable = []
        for v in range(n):
            connected = set()
            for u in range(n):
                if v in left_right[u]:
                    connected.add(u)
            if len(connected) < n and len(connected) > 0:
