import sys

def solve():
    n = int(input())

    def query(r1, c1, r2, c2):
        print(f"? {r1} {c1} {r2} {c2}")
        sys.stdout.flush()
        res = input().strip()
        if res == "BAD":
            exit()
        return res == "YES"

    def solve_path(r1, c1, r2, c2):
        """Return a path from (r1,c1) to (r2,c2)"""
        if r1 == r2 and c1 == c2:
            return ""

        # Check if we can go right
        can_right = False
        if query(r1, c1, r1, c1+1):
            can_right = query(r1, c1+1, r2, c2)

        # Check if we can go down
        can_down = False
        if query(r1, c1, r1+1, c1):
            can_down = query(r1+1, c1, r2, c2)

        # If we can go right, go right
        if can_right:
            return "R" + solve_path(r1, c1+1, r2, c2)

        # If we can go down, go down
        if can_down:
            return "D" + solve_path(r1+1, c1, r2, c2)

        return ""

    path = solve_path(1, 1, n, n)
    print(f"! {path}")
    sys.stdout.flush()

solve()
