    visited = [False] * (n + 1)
    max_t = 0

    for i in range(1, n + 1):
        if not visited[i]:
            current = i
            cycle = []
            while not visited[current]:
                visited[current] = True
                cycle.append(current)
                current = crush[current - 1]

            # Check for impossible case: self-loop with other people pointing to it
            if len(cycle) == 1:
                # This is a self-loop
                # Check if anyone else points to this person
                self_loop_person = cycle[0]
                has_other_pointing = False
                for person in range(1, n + 1):
                    if person != self_loop_person and crush[person - 1] == self_loop_person:
