    # We need to find the minimum number of columns to make magic
    # such that there is no path from (0,0) to (n-1, m-1)
    # This is essentially finding the minimum vertex cover in a grid graph
    #
    # Create bipartite graph
    left = []  # (i+j) even
    right = []  # (i+j) odd
    adj = [[] for _ in range(n * m)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if (i + j) % 2 == 0:
                    left.append((i, j))
                else:
                    right.append((i, j))

    # Build adjacency list
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i + 1 < n and grid[i+1][j] == '.':
                    adj[left.index((i, j))].append(right.index((i+1, j)))
                if j + 1 < m and grid[i][j+1] == '.':
                    adj[left.index((i, j))].append(right.index((i, j+1)))

    # Maximum bipartite matching
    def bpm(u, visited):
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if match_to[v] == -1 or bpm(match_to[v], visited):
