def find_min_magic_columns(grid, n, m):
    # We need to find the minimum number of columns to make magic
    # such that there is no path from (0,0) to (n-1, m-1)
    #
    # Create bipartite graph
    left = []  # (i+j) even
    right = []  # (i+j) odd
    adj = [[] for _ in range(len(left))]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if (i + j) % 2 == 0:
                    left.append((i, j))
                else:
                    right.append((i, j))

    # Build adjacency list from left to right
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                # Only add edges from left to right
                if (i + j) % 2 == 0:
                    # Current node is in left list
                    for (dx, dy) in [(0, 1), (1, 0)]:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                            # Neighbor is in right list
                            u = left.index((i, j))
                            v = right.index((ni, nj))
                            adj[u].append(v)

