        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if match_to[v] == -1 or bpm(match_to[v], visited):
                    match_to[v] = u
                    return True
        return False

    match_to = [-1] * len(right)
    result = 0

    for u in range(len(left)):
        visited = [False] * len(right)
        if bpm(u, visited):
