def compare_str(a, b):
    """Compare two large numbers represented as strings."""
    if len(a) < len(b):
        return -1
    elif len(a) > len(b):
        return 1
    else:
        # Same length, compare lexicographically
        return 1 if a > b else -1

def solve():
    MOD = 998244353

    # Read input
    a = input().strip()
    l = input().strip()
    r = input().strip()

    # Dynamic programming
    n = len(a)
    dp = [0] * (n + 1)
    dp[0] = 1  # Empty prefix

    for i in range(1, n + 1):
        # Try all possible substrings ending at position i-1
        for j in range(i):
            substring = a[j:i]

            # Check if substring is valid
            if len(substring) > len(l):
                continue
            if len(substring) < len(l):
                continue
            if len(substring) == len(l) and compare_str(substring, l) < 0:
                continue

            if len(substring) > len(r):
                continue
            if len(substring) < len(r):
                continue
            if len(substring) == len(r) and compare_str(substring, r) > 0:
                continue

            # Valid substring, update DP
            dp[i] = (dp[i] + dp[j]) % MOD

    print(dp[n])

