def is_winning(n):
    """Check if n is a winning position."""
    if n == 1:
        return False  # No moves, current player loses

    # Find all non-trivial divisors of n
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            if i != n:
                divisors.add(i)
            if n // i != n and n // i != i:
                divisors.add(n // i)

    # If no non-trivial divisors, current player loses
    if not divisors:
        return False

    # Check if any divisor leads to a losing position
    for d in divisors:
        if not is_winning(d):
            return True

    return False

def solve(q):
    """Solve the game for initial number q."""
    if q == 1:
        return (1, 0)

    divisors = set()
    for i in range(2, int(q**0.5) + 1):
        if q % i == 0:
            if i != q:
                divisors.add(i)
            if q // i != q and q // i != i:
                divisors.add(q // i)

    # Check if any divisor leads to a losing position
    for d in divisors:
        if not is_winning(d):
            return (1, d)

    # All divisors lead to winning positions, so current is losing
    return (2, 0)

q = int(input())
