    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find the longest contiguous segment that contains all books of a particular color
    max_length = 0

    # For each color, find the minimum and maximum index where it appears
    color_positions = {}
    for i, color in enumerate(a):
        if color not in color_positions:
            color_positions[color] = [i, i]
        else:
            color_positions[color][1] = i

    # For each color, check if all its positions are contiguous
    for color in color_positions:
        start, end = color_positions[color]
        # Check if all positions between start and end are occupied by this color
        all_contiguous = True
        for i in range(start, end + 1):
            if a[i] != color:
                all_contiguous = False
                break

        if all_contiguous:
            max_length = max(max_length, end - start + 1)

    print(n - max_length)

if __name__ == "__main__":
    solve()
