def is_winning(n, memo):
    """Determine if n is a winning position."""
    if n in memo:
        return memo[n]

    # Check if n has non-trivial divisors
    if n <= 3:
        # No non-trivial divisors (1, 2, 3)
        memo[n] = False  # Losing position (grundy 0)
        return False

    # Find all non-trivial divisors
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Check if all divisors are winning positions
    all_winning = True
    for d in divisors:
        if not is_winning(d, memo):
            all_winning = False
            break

    memo[n] = not all_winning  # Winning position if any divisor is losing
    return memo[n]

def find_winning_move(n, memo):
    """Find a winning first move for n."""
    if n <= 3:
        return 0  # No non-trivial divisors

    # Find all non-trivial divisors
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    # Find a divisor that is a losing position
    for d in divisors:
        if not is_winning(d, memo):
            return d

    return 0  # No winning move found

# Read input
q = int(input())

# Solve the problem
memo = {}
is_winning_q = is_winning(q, memo)

if not is_winning_q:
    # Player 1 cannot win
    print(2)
else:
    # Player 1 can win
    print(1)
    print(find_winning_move(q, memo))
