import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    max_len = 0
    left = 0
    bad_count = 0

    for right in range(n):
        while left < right and bad_count == 1:
            if a[left] >= a[left+1]:
                bad_count -= 1
            left += 1

        if a[right] >= a[right-1]:
            bad_count += 1

        max_len = max(max_len, right - left + 1)

    print(max_len)

if __name__ == "__main__":
    solve()
"}

