import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = defaultdict(set)
    edges = 0
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].add(v)
        adj[v].add(u)
        edges += 1

    # Find connected components
    visited = set()
    for node in range(1, n + 1):
        if node not in visited:
            # BFS to find all nodes in this component
            q = deque([node])
            visited.add(node)
            component = [node]
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        component.append(v)
                        q.append(v)

            k = len(component)
            if k >= 3:
                # Count edges in this component
                comp_edges = 0
                for i in range(k):
                    for j in range(i + 1, k):
                        if component[j] in adj[component[i]]:
                            comp_edges += 1

                if comp_edges != k * (k - 1) // 2:
                    print("NO")
                    return

    print("YES")

if __name__ == "__main__":
    solve()
"}

