    # If only one day, we can't form an arithmetic progression
    # But according to the problem, n >= 2
    pass
else:
    d = temperatures[1] - temperatures[0]

    # Check if all consecutive differences are equal to d
    is_ap = True
    for i in range(2, n):
        if temperatures[i] - temperatures[i-1] != d:
            is_ap = False
            break

    if is_ap:
        next_temp = temperatures[-1] + d
    else:
        next_temp = temperatures[-1]

